'use client';

import { cn } from '@/lib/utils';

/** The product mark: a shield with a terminal caret inside it.
 *
 *  ONE drawing, used everywhere. The product had three unrelated logos before
 *  this — a heart in favicon.ico, an infinity symbol in icon.png and a stock
 *  lucide shield glyph in the app — because each surface had picked its own.
 *
 *  The geometry is generated by wxt-agent/scripts/icon/make-icon.py, which
 *  emits this path, the macOS .icns and the web icons from the same numbers,
 *  so they cannot drift apart again. Edit the shape there, not here.
 *
 *  The shield takes `currentColor` so it inherits whatever it sits in; the
 *  caret is knocked out in a fixed near-black that reads on any accent. A
 *  surface that needs a different knockout sets `--mark-knockout`.
 */
export function BrandIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 100 100" fill="none" className={cn('shrink-0', className)} aria-hidden="true">
      <path
        d="M33.36 18.50H66.64A9.36 9.36 0 0 1 76.00 27.86V43.70Q76.00 74.90 50.00 78.50Q24.00 74.90 24.00 43.70V27.86A9.36 9.36 0 0 1 33.36 18.50Z"
        fill="currentColor"
      />
      <g
        stroke="var(--mark-knockout,#0c121c)"
        strokeWidth="4.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d="M38.8 38.0l8.2 8.2l-8.2 8.2" />
        <path d="M51.2 54.4h10.3" />
      </g>
    </svg>
  );
}
